INSERT INTO `t_user_role` (`user_id`, `role_id`) SELECT 1, id FROM `t_role` WHERE code = 'ADMIN';
INSERT INTO `t_user_role` (`user_id`, `role_id`) SELECT 2, id FROM `t_role` WHERE code = 'USER';
INSERT INTO `t_user_role` (`user_id`, `role_id`) SELECT 3, id FROM `t_role` WHERE code = 'CLUB_ADMIN';
INSERT INTO `t_user_role` (`user_id`, `role_id`) SELECT id, (SELECT id FROM `t_role` WHERE code='USER') FROM `t_user` WHERE username LIKE '20%';
INSERT INTO `t_club` (`id`, `name`, `short_name`, `category`, `description`, `founded_year`, `status`, `created_by`, `logo_url`, `created_at`, `updated_at`, `visit_count`, `balance`) VALUES (1, '程序设计协会（ACM）', 'ACM', '学术科技', '面向算法与竞赛编程爱好者，备战ICPC、CCPC等赛事，定期举办算法讲座和校内训练营。', 2018, 'ACTIVE', 105, 'https://images.unsplash.com/photo-1517694712202-14dd9538aa97?w=200&h=200&fit=crop', '2018-11-28 00:00:00', '2018-11-28 00:00:00', 3399, 4751);
INSERT INTO `t_club` (`id`, `name`, `short_name`, `category`, `description`, `founded_year`, `status`, `created_by`, `logo_url`, `created_at`, `updated_at`, `visit_count`, `balance`) VALUES (2, '开源技术社', 'OSC', '学术科技', '推广开源文化，参与校内外开源项目，学习Linux、Git及常用开发协作工具。', 2021, 'ACTIVE', 101, 'https://images.unsplash.com/photo-1556075798-4825dfaaf498?w=200&h=200&fit=crop', '2021-05-28 00:00:00', '2021-05-28 00:00:00', 4784, 1129);
INSERT INTO `t_club` (`id`, `name`, `short_name`, `category`, `description`, `founded_year`, `status`, `created_by`, `logo_url`, `created_at`, `updated_at`, `visit_count`, `balance`) VALUES (3, '人工智能协会', 'AI Lab', '学术科技', '围绕机器学习、计算机视觉和自然语言处理开展分享、项目实践与竞赛交流。', 2019, 'ACTIVE', 18, 'https://images.unsplash.com/photo-1677442135703-1787eea5ce01?w=200&h=200&fit=crop', '2019-11-24 00:00:00', '2019-11-24 00:00:00', 254, 2236);
INSERT INTO `t_club` (`id`, `name`, `short_name`, `category`, `description`, `founded_year`, `status`, `created_by`, `logo_url`, `created_at`, `updated_at`, `visit_count`, `balance`) VALUES (4, '无人机与航拍协会', 'Drone Club', '学术科技', '探索无人机飞行技术与航拍创作，记录校园活动与风景。', 2019, 'ACTIVE', 20, 'https://images.unsplash.com/photo-1473968512647-3e447244af8f?w=200&h=200&fit=crop', '2019-09-05 00:00:00', '2019-09-05 00:00:00', 2307, 1175);
INSERT INTO `t_club` (`id`, `name`, `short_name`, `category`, `description`, `founded_year`, `status`, `created_by`, `logo_url`, `created_at`, `updated_at`, `visit_count`, `balance`) VALUES (5, '数学建模社', 'Math Model', '学术科技', '数学建模竞赛交流平台，培养数据分析、论文写作与解决实际问题的能力。', 2020, 'ACTIVE', 89, 'https://images.unsplash.com/photo-1635070041078-e363dbe005cb?w=200&h=200&fit=crop', '2020-11-15 00:00:00', '2020-11-15 00:00:00', 4296, 2632);
INSERT INTO `t_club` (`id`, `name`, `short_name`, `category`, `description`, `founded_year`, `status`, `created_by`, `logo_url`, `created_at`, `updated_at`, `visit_count`, `balance`) VALUES (6, '吉他社', 'Guitar', '文化艺术', '聚集民谣、指弹与电吉他爱好者，定期举办排练、草坪歌会和新手教学。', 2021, 'ACTIVE', 171, 'https://images.unsplash.com/photo-1510915361894-db8b60106cb1?w=200&h=200&fit=crop', '2021-01-01 00:00:00', '2021-01-01 00:00:00', 4042, 4057);
