INSERT INTO `t_notice` (`club_id`, `title`, `content`, `scope`, `published_by`, `published_at`, `status`, `created_at`, `updated_at`) VALUES
  (1, '算法训练营第三周安排', '本周训练营聚焦最短路与状态压缩 DP，周三 19:00 在信科楼 B201 集合，提交补题截图后计入训练积分。', 'PUBLIC', 105, '2026-03-17 20:00:00', 'PUBLISHED', '2026-03-17 20:00:00', '2026-03-17 20:00:00'),
  (1, 'CCPC 校赛选拔说明', '春季校赛选拔将于周六上午进行，报名同学请在群文件填写常用题型与可参赛时段，现场统一配机。', 'PUBLIC', 105, '2026-03-10 19:30:00', 'PUBLISHED', '2026-03-10 19:30:00', '2026-03-10 19:30:00'),
  (1, '周末补题交流开放预约', '本周末开放 2 号机房作为补题交流场地，欢迎带上近期卡题记录到场讨论，值班学长会现场答疑。', 'PUBLIC', 105, '2026-02-26 21:00:00', 'PUBLISHED', '2026-02-26 21:00:00', '2026-02-26 21:00:00'),
  (1, 'ICPC 新生组队沟通会', '面向大一、大二成员开展组队沟通会，介绍组队分工、训练节奏和竞赛准备事项，建议提前整理个人擅长方向。', 'PUBLIC', 105, '2026-02-18 18:30:00', 'PUBLISHED', '2026-02-18 18:30:00', '2026-02-18 18:30:00'),
  (1, '寒假打卡总结与春训预告', '寒假算法打卡统计已完成，完成率前十的同学将优先进入春训强化名单，详细安排已同步到社团文档。', 'PUBLIC', 105, '2026-01-12 20:10:00', 'PUBLISHED', '2026-01-12 20:10:00', '2026-01-12 20:10:00'),
  (2, 'Git 与协作开发工作坊报名', '本周工作坊围绕分支管理、Pull Request 和 Code Review 展开，零基础成员也可参加，活动后会发放练习仓库地址。', 'PUBLIC', 101, '2026-03-16 19:00:00', 'PUBLISHED', '2026-03-16 19:00:00', '2026-03-16 19:00:00'),
  (2, '校园开源之夏宣讲预告', '社团将介绍开源之夏项目选择方法、导师沟通技巧和往届成员经验，欢迎有意参与同学提前准备问题。', 'PUBLIC', 101, '2026-03-08 18:40:00', 'PUBLISHED', '2026-03-08 18:40:00', '2026-03-08 18:40:00'),
  (2, 'Linux 入门夜谈活动安排', '本期夜谈聚焦常用命令、环境配置和远程连接操作，建议自带电脑现场完成开发环境初始化。', 'PUBLIC', 101, '2026-02-25 20:15:00', 'PUBLISHED', '2026-02-25 20:15:00', '2026-02-25 20:15:00'),
  (2, 'Spring Boot 协作项目结项展示', '本学期协作项目进入展示阶段，各小组需准备 5 分钟演示与仓库说明，展示顺序已更新到群公告。', 'PUBLIC', 101, '2026-02-12 19:20:00', 'PUBLISHED', '2026-02-12 19:20:00', '2026-02-12 19:20:00'),
  (2, '开源仓库维护值班表发布', '社团公共仓库的 issue 值班表已公布，值班成员请按时跟进问题反馈，保持 README 与发布记录同步。', 'PUBLIC', 101, '2026-01-15 18:50:00', 'PUBLISHED', '2026-01-15 18:50:00', '2026-01-15 18:50:00'),
  (3, '大模型应用分享会开放报名', '分享会将展示校园问答、社团推荐等落地案例，并安排现场体验环节，席位有限请尽快报名。', 'PUBLIC', 18, '2026-03-15 19:10:00', 'PUBLISHED', '2026-03-15 19:10:00', '2026-03-15 19:10:00'),
  (3, '机器学习读书会第六期安排', '本期阅读内容为特征工程与模型评估章节，主讲同学需在周五前上传导读 PPT。', 'PUBLIC', 18, '2026-03-07 20:00:00', 'PUBLISHED', '2026-03-07 20:00:00', '2026-03-07 20:00:00'),
  (3, 'OCR 校园导览项目招募成员', '导览项目进入数据采集阶段，现招募负责图像清洗、标注和前端展示的同学各 2 名。', 'PUBLIC', 18, '2026-02-24 18:20:00', 'PUBLISHED', '2026-02-24 18:20:00', '2026-02-24 18:20:00'),
  (3, '数据标注志愿分工表已更新', '本周新增宿舍区与食堂场景数据，参与标注的成员请按分工表在周末前完成第一轮校验。', 'PUBLIC', 18, '2026-02-11 21:10:00', 'PUBLISHED', '2026-02-11 21:10:00', '2026-02-11 21:10:00'),
  (3, '校级智能应用赛组队说明', '准备参加校级智能应用赛的成员请在表单中填写擅长方向，社团将根据算法、前端和产品分工统一组队。', 'PUBLIC', 18, '2026-01-20 19:40:00', 'PUBLISHED', '2026-01-20 19:40:00', '2026-01-20 19:40:00'),
  (4, '春季航拍安全培训通知', '所有计划参与本学期飞行任务的成员需参加安全培训，未签到者暂不开放设备借用权限。', 'PUBLIC', 20, '2026-03-14 17:30:00', 'PUBLISHED', '2026-03-14 17:30:00', '2026-03-14 17:30:00'),
  (4, '校园花海航拍采风安排', '本周日早上 7:00 在南门集合，统一前往花海区域采风，风速较大时将改为地面取景练习。', 'PUBLIC', 20, '2026-03-06 16:50:00', 'PUBLISHED', '2026-03-06 16:50:00', '2026-03-06 16:50:00'),
  (4, '飞手考核名单与时段公布', '新飞手考核安排在操场西侧空地进行，请根据名单提前 15 分钟到场完成设备检查。', 'PUBLIC', 20, '2026-02-23 18:00:00', 'PUBLISHED', '2026-02-23 18:00:00', '2026-02-23 18:00:00'),
  (4, '设备借用登记本周开放', '航拍设备借用采用线上登记加现场确认方式，归还时需同步上传飞行记录与素材目录。', 'PUBLIC', 20, '2026-02-09 20:30:00', 'PUBLISHED', '2026-02-09 20:30:00', '2026-02-09 20:30:00'),
  (4, '航拍作品素材整理提醒', '寒假素材已统一归档，请各小组在周三前完成命名规范自查，优秀作品将用于春季宣传片剪辑。', 'PUBLIC', 20, '2026-01-18 19:10:00', 'PUBLISHED', '2026-01-18 19:10:00', '2026-01-18 19:10:00'),
  (5, '美赛复盘分享会安排', '分享会由获奖队伍复盘建模流程、论文结构和时间分配，欢迎准备参赛的同学提前阅读优秀论文。', 'PUBLIC', 89, '2026-03-13 19:30:00', 'PUBLISHED', '2026-03-13 19:30:00', '2026-03-13 19:30:00'),
  (5, '国赛组队意向征集', '国赛备赛进入组队阶段，社团建议每队尽量覆盖建模、编程与写作三类分工，意向表本周日晚关闭。', 'PUBLIC', 89, '2026-03-05 20:20:00', 'PUBLISHED', '2026-03-05 20:20:00', '2026-03-05 20:20:00'),
  (5, 'LaTeX 排版 workshop 报名', '本次 workshop 讲解数学公式、参考文献和图表排版，适合准备竞赛论文和科研报告的同学参加。', 'PUBLIC', 89, '2026-02-22 18:40:00', 'PUBLISHED', '2026-02-22 18:40:00', '2026-02-22 18:40:00'),
  (5, '数据分析练习题第 4 期发布', '本期练习围绕聚类分析与可视化展开，提交截止后会统一讲解常见建模误区。', 'PUBLIC', 89, '2026-02-08 21:00:00', 'PUBLISHED', '2026-02-08 21:00:00', '2026-02-08 21:00:00'),
  (5, '寒假论文阅读打卡总结', '寒假阅读打卡统计已完成，累计阅读篇数和笔记质量将作为春季项目组优先录取参考。', 'PUBLIC', 89, '2026-01-16 19:15:00', 'PUBLISHED', '2026-01-16 19:15:00', '2026-01-16 19:15:00'),
  (6, '草坪音乐会第一次合排通知', '第一次合排安排在周四晚操场草坪，请携带谱夹和常用线材，现场按节目单顺序依次试音。', 'PUBLIC', 171, '2026-03-12 18:30:00', 'PUBLISHED', '2026-03-12 18:30:00', '2026-03-12 18:30:00'),
  (6, '新手和弦课本周教室调整', '受教室临时借用影响，本周新手课改到艺术楼 103 教室，课程内容和时间保持不变。', 'PUBLIC', 171, '2026-03-04 19:00:00', 'PUBLISHED', '2026-03-04 19:00:00', '2026-03-04 19:00:00'),
  (6, '校园歌手大赛伴奏招募', '需要吉他伴奏的参赛同学可在社团表单登记，社团将根据曲风安排伴奏成员和排练时间。', 'PUBLIC', 171, '2026-02-21 20:30:00', 'PUBLISHED', '2026-02-21 20:30:00', '2026-02-21 20:30:00'),
  (6, '周末开放练琴时段公告', '本周六下午开放排练室供成员自由练琴，请提前预约时段并保持设备摆放整齐。', 'PUBLIC', 171, '2026-02-07 17:50:00', 'PUBLISHED', '2026-02-07 17:50:00', '2026-02-07 17:50:00'),
  (6, '春季开放日节目征集', '春季开放日面向全体成员征集独奏、合奏与原创节目，入选节目将获得优先排练档期。', 'PUBLIC', 171, '2026-01-14 18:45:00', 'PUBLISHED', '2026-01-14 18:45:00', '2026-01-14 18:45:00'),
  (7, '周五剧本夜分组名单公布', '本周剧本夜分为新手组与进阶组两场，名单和角色卡领取方式已同步到群文件。', 'PUBLIC', 85, '2026-03-11 20:10:00', 'PUBLISHED', '2026-03-11 20:10:00', '2026-03-11 20:10:00'),
  (7, 'DM 培训第二讲安排', '第二讲将围绕控场节奏和玩家情绪引导展开，参加培训的成员请提前阅读示例流程。', 'PUBLIC', 85, '2026-03-03 19:30:00', 'PUBLISHED', '2026-03-03 19:30:00', '2026-03-03 19:30:00'),
  (7, '原创本试玩志愿者招募', '原创校园题材剧本进入内测阶段，需要 8 名试玩志愿者反馈节奏、线索量与沉浸感体验。', 'PUBLIC', 85, '2026-02-20 21:20:00', 'PUBLISHED', '2026-02-20 21:20:00', '2026-02-20 21:20:00'),
  (7, '沉浸式活动场务说明', '周末沉浸式活动需提前完成道具摆放与动线确认，场务同学请按分工表到场签到。', 'PUBLIC', 85, '2026-02-06 18:10:00', 'PUBLISHED', '2026-02-06 18:10:00', '2026-02-06 18:10:00'),
  (7, '学期首次桌游体验夜预告', '社团将在本周开放基础桌游体验夜，欢迎新成员熟悉规则并结识固定队友。', 'PUBLIC', 85, '2026-01-13 20:00:00', 'PUBLISHED', '2026-01-13 20:00:00', '2026-01-13 20:00:00'),
  (8, '上巳节游园拍摄报名开启', '上巳节主题游园定于下周六举行，报名同学请在表单中勾选服装、妆造和拍摄需求。', 'PUBLIC', 205, '2026-03-10 18:00:00', 'PUBLISHED', '2026-03-10 18:00:00', '2026-03-10 18:00:00'),
  (8, '礼仪课第三次训练安排', '本周礼仪课练习行礼、步态和团体出场站位，请准时到传统文化教室集合。', 'PUBLIC', 205, '2026-03-02 19:10:00', 'PUBLISHED', '2026-03-02 19:10:00', '2026-03-02 19:10:00'),
  (8, '春季服装借用流程说明', '春季活动服装借用改为线上预约、线下核验双流程，逾期归还将影响后续活动优先报名资格。', 'PUBLIC', 205, '2026-02-19 20:10:00', 'PUBLISHED', '2026-02-19 20:10:00', '2026-02-19 20:10:00'),
  (8, '妆造体验日值班表发布', '妆造体验日分上午和下午两场，值班成员请提前准备发饰、妆面工具和消毒用品。', 'PUBLIC', 205, '2026-02-05 18:30:00', 'PUBLISHED', '2026-02-05 18:30:00', '2026-02-05 18:30:00'),
  (8, '传统文化分享会时间调整', '因报告厅排期变化，分享会调整到周日晚 7 点，请已报名同学注意签到时间。', 'PUBLIC', 205, '2026-01-11 19:20:00', 'PUBLISHED', '2026-01-11 19:20:00', '2026-01-11 19:20:00'),
  (9, '春季公演集训日程表发布', '公演进入集训阶段，各舞种排练时段与负责人已更新，请大家按表参加并完成打卡。', 'PUBLIC', 129, '2026-03-09 20:20:00', 'PUBLISHED', '2026-03-09 20:20:00', '2026-03-09 20:20:00'),
  (9, '新队员分组与考勤说明', '新成员已完成基础测试，本周起按 Hip-hop、Popping 与 Breaking 三组分别训练。', 'PUBLIC', 129, '2026-03-01 18:50:00', 'PUBLISHED', '2026-03-01 18:50:00', '2026-03-01 18:50:00'),
  (9, 'Breaking 公开课开放旁听', '公开课邀请校外老师授课，旁听名额面向全校开放，社团成员可优先入场。', 'PUBLIC', 129, '2026-02-18 19:30:00', 'PUBLISHED', '2026-02-18 19:30:00', '2026-02-18 19:30:00'),
  (9, '表演服尺码统计提醒', '公演表演服开始统计尺码，本周五 22:00 截止，逾期将统一按常规码下单。', 'PUBLIC', 129, '2026-02-04 21:00:00', 'PUBLISHED', '2026-02-04 21:00:00', '2026-02-04 21:00:00'),
  (9, '期初基础训练签到规则', '新学期训练恢复线上签到，连续缺勤两次以上需向对应队长说明情况。', 'PUBLIC', 129, '2026-01-10 18:40:00', 'PUBLISHED', '2026-01-10 18:40:00', '2026-01-10 18:40:00'),
  (10, '四月主题展筹备会通知', '主题展将展示插画、手办与原创周边作品，筹备会将确定展区分工和布置方案。', 'PUBLIC', 14, '2026-03-08 19:40:00', 'PUBLISHED', '2026-03-08 19:40:00', '2026-03-08 19:40:00'),
  (10, '插画打卡计划第三周题目', '第三周主题为春日校园，请在周日前上传 1 张完整作品并附上配色思路说明。', 'PUBLIC', 14, '2026-02-28 20:15:00', 'PUBLISHED', '2026-02-28 20:15:00', '2026-02-28 20:15:00'),
  (10, 'Cos 外拍安全提醒与集合点', '本周外拍统一在图书馆北侧集合，请参与成员自行准备应急用品并遵守公共秩序。', 'PUBLIC', 14, '2026-02-17 18:20:00', 'PUBLISHED', '2026-02-17 18:20:00', '2026-02-17 18:20:00'),
  (10, '原创本交换会摊位征集', '社团计划举办原创本交换会，欢迎带来同人本、设定集和原创明信片参与交流。', 'PUBLIC', 14, '2026-02-03 19:00:00', 'PUBLISHED', '2026-02-03 19:00:00', '2026-02-03 19:00:00'),
  (10, '学期作品墙更新说明', '本学期第一批作品墙已经更换，入选作品电子海报已发给作者，欢迎继续投稿原创内容。', 'PUBLIC', 14, '2026-01-09 20:10:00', 'PUBLISHED', '2026-01-09 20:10:00', '2026-01-09 20:10:00');
INSERT INTO `t_notice` (`club_id`, `title`, `content`, `scope`, `published_by`, `published_at`, `status`, `created_at`, `updated_at`) VALUES
  (11, '樱花季外拍分组安排', '本次外拍分为人像、风景和纪实三个小组，负责同学请提前确认机位和集合路线。', 'PUBLIC', 24, '2026-03-07 18:30:00', 'PUBLISHED', '2026-03-07 18:30:00', '2026-03-07 18:30:00'),
  (11, 'Lightroom 调色分享会报名', '分享会将演示基础调色流程、肤色统一和夜景降噪处理，欢迎自带样片现场练习。', 'PUBLIC', 24, '2026-02-27 20:00:00', 'PUBLISHED', '2026-02-27 20:00:00', '2026-02-27 20:00:00'),
  (11, '校运会拍摄志愿者征集', '社团需要补充赛道、颁奖和后台记录机位的志愿者，参与同学可计入活动服务时长。', 'PUBLIC', 24, '2026-02-16 19:10:00', 'PUBLISHED', '2026-02-16 19:10:00', '2026-02-16 19:10:00'),
  (11, '本月优秀作品征集说明', '二月优秀作品评选开始征集，投稿需附拍摄地点、设备信息和 100 字以内创作说明。', 'PUBLIC', 24, '2026-02-02 18:20:00', 'PUBLISHED', '2026-02-02 18:20:00', '2026-02-02 18:20:00'),
  (11, '摄影器材借用规范更新', '器材借用流程已更新为线上审批，领取与归还均需现场核验配件数量。', 'PUBLIC', 24, '2026-01-08 19:30:00', 'PUBLISHED', '2026-01-08 19:30:00', '2026-01-08 19:30:00'),
  (12, '春季联赛抽签结果公布', '院系联赛抽签结果已出炉，首轮比赛时间和对阵表请查看附件，队员注意赛前热身。', 'PUBLIC', 45, '2026-03-06 20:10:00', 'PUBLISHED', '2026-03-06 20:10:00', '2026-03-06 20:10:00'),
  (12, '裁判培训时间确认', '本次裁判培训安排在体育馆副馆进行，需参与执裁的成员请准时签到并携带哨子。', 'PUBLIC', 45, '2026-02-26 18:50:00', 'PUBLISHED', '2026-02-26 18:50:00', '2026-02-26 18:50:00'),
  (12, '周末加练分组与场地安排', '本周末安排投篮组、对抗组和体能组分别训练，场地使用时间已和体院协调完成。', 'PUBLIC', 45, '2026-02-15 19:40:00', 'PUBLISHED', '2026-02-15 19:40:00', '2026-02-15 19:40:00'),
  (12, '球衣尺码统计本周截止', '新赛季球衣制作进入统计阶段，请队员按实际需求填写尺码，避免后续集中调换。', 'PUBLIC', 45, '2026-02-01 21:10:00', 'PUBLISHED', '2026-02-01 21:10:00', '2026-02-01 21:10:00'),
  (12, '校队选拔体测提醒', '参与校队选拔的同学需在周五前完成折返跑和立定跳远测试，逾期视为自动放弃。', 'PUBLIC', 45, '2026-01-07 18:10:00', 'PUBLISHED', '2026-01-07 18:10:00', '2026-01-07 18:10:00'),
  (13, '双打固定搭档登记开启', '社团开始统计春季双打固定搭档，请有意参加友谊赛的成员尽快登记组合与常打位置。', 'PUBLIC', 227, '2026-03-05 19:20:00', 'PUBLISHED', '2026-03-05 19:20:00', '2026-03-05 19:20:00'),
  (13, '本周场地预约时段公布', '训练场地分为基础练习和对抗两类时段，请根据自身节奏预约，避免扎堆占场。', 'PUBLIC', 227, '2026-02-25 18:30:00', 'PUBLISHED', '2026-02-25 18:30:00', '2026-02-25 18:30:00'),
  (13, '校际友谊赛报名通知', '本月下旬将与兄弟院校进行友谊赛，参赛成员需先参加一次队内对抗选拔。', 'PUBLIC', 227, '2026-02-14 20:00:00', 'PUBLISHED', '2026-02-14 20:00:00', '2026-02-14 20:00:00'),
  (13, '发球专项训练安排', '本周专项训练聚焦高远发球与反手发球稳定性，建议提前热身保护手腕。', 'PUBLIC', 227, '2026-01-31 19:15:00', 'PUBLISHED', '2026-01-31 19:15:00', '2026-01-31 19:15:00'),
  (14, '三月夜跑路线与集合点', '三月夜跑主路线更新为东操场至滨湖步道往返，全程约 6 公里，集合点仍在图书馆南门。', 'PUBLIC', 134, '2026-03-04 20:30:00', 'PUBLISHED', '2026-03-04 20:30:00', '2026-03-04 20:30:00'),
  (14, '配速分组名单更新', '根据上周测试成绩，配速组调整为 5 分组、6 分组和轻松跑组，请按分组跟跑。', 'PUBLIC', 134, '2026-02-24 19:00:00', 'PUBLISHED', '2026-02-24 19:00:00', '2026-02-24 19:00:00'),
  (14, '半马训练计划第一阶段说明', '有意参加半马的成员请从本周开始完成基础耐力训练，并按要求提交每次心率记录。', 'PUBLIC', 134, '2026-02-13 18:40:00', 'PUBLISHED', '2026-02-13 18:40:00', '2026-02-13 18:40:00'),
  (14, '雨天改室内拉伸通知', '若今晚 18:30 后持续降雨，夜跑活动改为体育馆室内拉伸与核心训练，请注意群消息。', 'PUBLIC', 134, '2026-01-30 20:00:00', 'PUBLISHED', '2026-01-30 20:00:00', '2026-01-30 20:00:00'),
  (15, '校园联赛参赛名单公示', '本次校园联赛最终报名名单已完成审核，请入选队员确认比赛账号与备用联系方式。', 'PUBLIC', 141, '2026-03-03 21:00:00', 'PUBLISHED', '2026-03-03 21:00:00', '2026-03-03 21:00:00'),
  (15, '战术复盘会改至今晚 8 点', '受机房使用安排影响，复盘会顺延半小时开始，主要复盘上周训练赛的视野与团战配合。', 'PUBLIC', 141, '2026-02-23 20:10:00', 'PUBLISHED', '2026-02-23 20:10:00', '2026-02-23 20:10:00'),
  (15, '解说与后勤志愿者招募', '赛事直播和现场组织需要补充解说、导播与签到志愿者，欢迎非选手成员报名支持。', 'PUBLIC', 141, '2026-02-12 19:00:00', 'PUBLISHED', '2026-02-12 19:00:00', '2026-02-12 19:00:00'),
  (15, '训练室值日安排发布', '训练室卫生与设备管理值日表已更新，值日同学请完成外设归位和网络设备检查。', 'PUBLIC', 141, '2026-01-29 18:50:00', 'PUBLISHED', '2026-01-29 18:50:00', '2026-01-29 18:50:00'),
  (16, '安全护具检查周开启', '本周为护具检查周，参加刷街或动作训练的成员请佩戴齐全头盔、护肘与护膝。', 'PUBLIC', 224, '2026-03-02 18:10:00', 'PUBLISHED', '2026-03-02 18:10:00', '2026-03-02 18:10:00'),
  (16, '新动作教学开放旁听', '本周教学内容为基础 Ollie 稳定性与下台动作，旁听成员请在开始前完成热身。', 'PUBLIC', 224, '2026-02-22 17:50:00', 'PUBLISHED', '2026-02-22 17:50:00', '2026-02-22 17:50:00'),
  (16, '周末刷街集合时间提醒', '周六上午 8:30 在体育馆北门集合，统一前往江边绿道，迟到超过 10 分钟的成员请自行前往会合点。', 'PUBLIC', 224, '2026-02-11 19:20:00', 'PUBLISHED', '2026-02-11 19:20:00', '2026-02-11 19:20:00'),
  (16, '场地维护志愿者名单公布', '社团将对练习区域进行清洁和简单修补，志愿者请携带手套和清洁工具按时到场。', 'PUBLIC', 224, '2026-01-28 20:30:00', 'PUBLISHED', '2026-01-28 20:30:00', '2026-01-28 20:30:00'),
  (17, '敬老院服务活动招募', '周末敬老院活动现招募陪伴、表演和后勤成员，报名成功后统一参加行前培训。', 'PUBLIC', 68, '2026-03-01 18:40:00', 'PUBLISHED', '2026-03-01 18:40:00', '2026-03-01 18:40:00'),
  (17, '图书整理值班表更新', '本周图书馆整理志愿服务改为分时段签到，请值班同学注意新表中的到岗时间。', 'PUBLIC', 68, '2026-02-21 19:10:00', 'PUBLISHED', '2026-02-21 19:10:00', '2026-02-21 19:10:00'),
  (17, '周末环保行动集合通知', '环保行动将在宿舍区和湖边同步开展，请参与成员自备水杯与手套，现场领取垃圾袋。', 'PUBLIC', 68, '2026-02-10 20:20:00', 'PUBLISHED', '2026-02-10 20:20:00', '2026-02-10 20:20:00'),
  (17, '志愿时长登记流程说明', '本学期志愿时长改为活动结束后 48 小时内线上登记，逾期需联系负责人补录。', 'PUBLIC', 68, '2026-01-27 18:00:00', 'PUBLISHED', '2026-01-27 18:00:00', '2026-01-27 18:00:00'),
  (18, '流浪猫绝育回访安排', '本周将对已完成绝育的校园流浪猫进行回访观察，负责同学请按点位记录状态与照片。', 'PUBLIC', 74, '2026-02-28 19:30:00', 'PUBLISHED', '2026-02-28 19:30:00', '2026-02-28 19:30:00'),
  (18, '周末领养日流程说明', '领养日分为登记、面谈和家访说明三个环节，志愿者需提前半小时完成物资布置。', 'PUBLIC', 74, '2026-02-20 18:20:00', 'PUBLISHED', '2026-02-20 18:20:00', '2026-02-20 18:20:00'),
  (18, '猫粮捐赠公示与感谢名单', '三月第一批猫粮与药品捐赠明细已公示，感谢参与支持的老师和同学。', 'PUBLIC', 74, '2026-02-09 21:10:00', 'PUBLISHED', '2026-02-09 21:10:00', '2026-02-09 21:10:00'),
  (18, '校园喂食点巡查分工', '常用喂食点本周起实行双人巡查制度，请按分工拍照记录并上报异常情况。', 'PUBLIC', 74, '2026-01-26 19:40:00', 'PUBLISHED', '2026-01-26 19:40:00', '2026-01-26 19:40:00'),
  (19, 'CPR 培训开放补报名', '因前期报名名额已满，本周新增一场补报名培训，请有需要的同学尽快提交信息。', 'PUBLIC', 64, '2026-02-27 18:10:00', 'PUBLISHED', '2026-02-27 18:10:00', '2026-02-27 18:10:00'),
  (19, '无偿献血志愿者招募通知', '下周校医院将组织无偿献血活动，社团需要补充现场引导和信息核验志愿者。', 'PUBLIC', 64, '2026-02-19 20:00:00', 'PUBLISHED', '2026-02-19 20:00:00', '2026-02-19 20:00:00'),
  (19, '医药箱检查结果公示', '各社团活动医药箱的检查结果已完成汇总，缺失物资清单请相关负责人本周内补齐。', 'PUBLIC', 64, '2026-02-08 17:50:00', 'PUBLISHED', '2026-02-08 17:50:00', '2026-02-08 17:50:00'),
  (19, '防艾宣传周物资领取说明', '宣传周展板、手册和徽章已准备完毕，负责摊位的同学请在活动前一天领取。', 'PUBLIC', 64, '2026-01-25 18:30:00', 'PUBLISHED', '2026-01-25 18:30:00', '2026-01-25 18:30:00'),
  (20, '商业计划书工作坊报名开启', '工作坊将从市场分析、盈利模式和路演表达三个部分讲解，适合有创业想法的同学参加。', 'PUBLIC', 11, '2026-02-26 19:20:00', 'PUBLISHED', '2026-02-26 19:20:00', '2026-02-26 19:20:00'),
  (20, '路演彩排分组安排', '本周路演彩排按照互联网、文创和公益项目三组进行，每组限时 8 分钟展示。', 'PUBLIC', 11, '2026-02-18 18:40:00', 'PUBLISHED', '2026-02-18 18:40:00', '2026-02-18 18:40:00'),
  (20, '创业导师面谈预约表发布', '社团邀请校友创业导师开展一对一沟通，预约表已开放，请提前准备项目简介。', 'PUBLIC', 11, '2026-02-07 20:10:00', 'PUBLISHED', '2026-02-07 20:10:00', '2026-02-07 20:10:00'),
  (20, '创新集市摊位征集通知', '四月创新集市开始征集展示摊位，入选项目可获得学校场地与宣传支持。', 'PUBLIC', 11, '2026-01-24 19:00:00', 'PUBLISHED', '2026-01-24 19:00:00', '2026-01-24 19:00:00'),
  (21, '简历门诊本周预约开放', '简历门诊将提供一对一修改建议，报名同学请提前上传 PDF 简历以便老师批注。', 'PUBLIC', 103, '2026-02-25 20:20:00', 'PUBLISHED', '2026-02-25 20:20:00', '2026-02-25 20:20:00'),
  (21, '面试模拟周排班说明', '模拟周按照技术岗、产品岗和运营岗分别设置场次，请同学按目标岗位预约。', 'PUBLIC', 103, '2026-02-17 18:10:00', 'PUBLISHED', '2026-02-17 18:10:00', '2026-02-17 18:10:00'),
  (21, 'Offer 分享会嘉宾名单公布', '本次分享会邀请到互联网、制造业和国企方向的学长学姐，欢迎带着问题到场交流。', 'PUBLIC', 103, '2026-02-06 19:30:00', 'PUBLISHED', '2026-02-06 19:30:00', '2026-02-06 19:30:00'),
  (21, '企业参访报名须知', '企业参访名额有限，报名后需在出发前提交身份证明与安全承诺书。', 'PUBLIC', 103, '2026-01-23 18:50:00', 'PUBLISHED', '2026-01-23 18:50:00', '2026-01-23 18:50:00'),
  (22, '周会背景文件已上传', '本周议题背景文件与国家立场材料已上传至共享盘，请各代表在例会前完成阅读。', 'PUBLIC', 7, '2026-02-24 19:40:00', 'PUBLISHED', '2026-02-24 19:40:00', '2026-02-24 19:40:00'),
  (22, '议题培训第二讲时间调整', '因报告厅临时排期变动，第二讲改到周日晚上进行，内容仍聚焦立场文件写作。', 'PUBLIC', 7, '2026-02-16 18:30:00', 'PUBLISHED', '2026-02-16 18:30:00', '2026-02-16 18:30:00'),
  (22, '校际会议报名通道开启', '本次校际会议优先面向完成内训的成员开放报名，请注意截止时间与席位选择。', 'PUBLIC', 7, '2026-02-05 20:00:00', 'PUBLISHED', '2026-02-05 20:00:00', '2026-02-05 20:00:00'),
  (22, '立场文件提交截止提醒', '下周一中午前需提交第一版立场文件，主席团将统一反馈格式和论证问题。', 'PUBLIC', 7, '2026-01-22 19:10:00', 'PUBLISHED', '2026-01-22 19:10:00', '2026-01-22 19:10:00');
